@Component("bankingProduct-handler")
@ProcessingGroup("bankingProduct-processing-group")
public class BankingProductEventHandler {
	
	// core constructor
	BankingProductEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateBankingProductEvent
     */
    @EventHandler
    public void handle( CreateBankingProductEvent event) {
        entityManager.persist(new BankingProduct(event.getBankingProductId(), event.getProductCode(), event.getName(), event.getDescription(), event.getBank(), event.getAccounts(), event.getLoanAccounts(), event.getPaymentCards(), event.getProductCategory()));
    }

    /*
     * @param	event UpdateBankingProductEvent
     */
    @EventHandler
    public BankingProduct handle( UpdateBankingProductEvent event) {
    	entityManager.merge(new BankingProduct(event.getBankingProductId(), event.getProductCode(), event.getName(), event.getDescription(), event.getBank(), event.getAccounts(), event.getLoanAccounts(), event.getPaymentCards(), event.getProductCategory()));
    }
    
    /*
     * @param	event DeleteBankingProductEvent
     */
    @EventHandler
    public void on( DeleteBankingProductEvent event) {
    	BankingProduct entity = new BankingProduct();
   
    	// ------------------------------------------
    	// apply the BankingProductId
    	// ------------------------------------------
    	entity.setBankingProductId( event.getBankingProductId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final BankingProductRepository bankingProductEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(BankingProductEventHandler.class.getName());

}
